// NTP Time for M5Stack (ESP32)
#include <M5Stack.h>
#include <WiFi.h>
#include "secrets.h" // Файл должен содержать: const char* SECRET_SSID = "..."; const char* SECRET_PASS = "...";

const char* ntpServer = "pool.ntp.org";
// Смещение для Москвы (UTC+3). Укажите свое, если другой регион.
const long gmtOffsetSec = 3 * 3600; 
const int daylightOffsetSec = 0; // DST лучше обрабатывать логикой внутри скетча, либо ставить 3600 летом

void setup() {
  // Инициализация ядра M5Stack (включает Serial.begin(115200))
  M5.begin();

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setTextColor(WHITE);
  M5.Lcd.setTextSize(2);
  M5.Lcd.setCursor(10, 10);
  M5.Lcd.println("Connecting to WiFi...");

  WiFi.begin(SECRET_SSID, SECRET_PASS);
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    M5.Lcd.print(".");
  }

  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setCursor(10, 10);
  M5.Lcd.println("WiFi OK");
  Serial.println("\nWiFi OK");

  configTime(gmtOffsetSec, daylightOffsetSec, ntpServer);
  Serial.println("Waiting for NTP sync...");
}

void loop() {
  M5.update(); // Обязательно для обработки кнопок M5Stack

  struct tm timeinfo;
  // Используем time() + localtime_r() вместо getLocalTime()
  time_t now = time(nullptr);
  localtime_r(&now, &timeinfo);

  if (!timeinfo.tm_year) {
    Serial.println("Time not synced yet");
    M5.Lcd.fillScreen(BLACK);
    M5.Lcd.setCursor(10, 10);
    M5.Lcd.println("Time not synced yet");
    delay(1000);
    return;
  }

  char buf[64];
  strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &timeinfo);

  Serial.println(buf);

  // Вывод на экран M5Stack
  M5.Lcd.fillScreen(BLACK);
  M5.Lcd.setCursor(10, 50); // Сдвигаем ниже, чтобы не сливалось с верхней строкой
  M5.Lcd.println(buf);

  delay(1000);
}
